const config = { ...$json };
const zone = config.timezone || 'America/Los_Angeles';
const now = $now.setZone(zone);
const reportMonth = now.minus({ months: 1 }).startOf('month');
const previousMonth = reportMonth.minus({ months: 1 }).startOf('month');

return [{
  json: {
    ...config,
    today: now.toISODate(),
    report_month: reportMonth.toISODate(),
    period_start: reportMonth.toISODate(),
    period_end: reportMonth.endOf('month').toISODate(),
    previous_period_start: previousMonth.toISODate(),
    previous_period_end: previousMonth.endOf('month').toISODate(),
    report_month_label: reportMonth.toFormat('LLLL yyyy'),
    title: 'Monthly Performance Report - ' + reportMonth.toFormat('LLLL yyyy')
  }
}];

const config = $('Calculate Report Periods').first().json;
const rows = $('Fetch Existing Monthly Report').all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]).filter((row) => row && row.id);
const existing = rows[0] || null;
return [{ json: { ...config, existing_report_id: existing?.id || null, existing_status: existing?.status || null, skip_published: existing?.status === 'published' } }];

const config = $('Check Existing Report Status').first().json;

function rows(name) {
  return $(name).all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]).filter(Boolean);
}
function num(value) {
  if (value === null || value === undefined || value === '') return 0;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
function nullableNum(value) {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}
function pctChange(current, previous) {
  if (current === null || current === undefined || previous === null || previous === undefined || previous === 0) return null;
  return (current - previous) / previous;
}
function ratio(numerator, denominator) {
  return denominator > 0 ? numerator / denominator : null;
}
function campaignName(row) {
  return row.campaign_name || row.campaign_id || 'Unknown campaign';
}
function aggregatePaid(rawRows) {
  if (!rawRows.length) return null;
  const byCampaign = new Map();
  const totals = { spend: 0, revenue: 0, conversion_value: 0, conversions: 0, clicks: 0, impressions: 0 };
  for (const row of rawRows) {
    const spend = num(row.spend);
    const revenue = num(row.revenue ?? row.conversion_value);
    const conversions = num(row.conversions);
    const clicks = num(row.clicks);
    const impressions = num(row.impressions);
    totals.spend += spend;
    totals.revenue += revenue;
    totals.conversion_value += revenue;
    totals.conversions += conversions;
    totals.clicks += clicks;
    totals.impressions += impressions;
    const key = String(row.platform || '') + '|' + String(row.campaign_id || campaignName(row));
    const current = byCampaign.get(key) || { campaign_name: campaignName(row), platform: row.platform || null, channel: row.channel || null, spend: 0, revenue: 0, conversion_value: 0, conversions: 0, clicks: 0, impressions: 0, wasted_spend: 0 };
    current.spend += spend;
    current.revenue += revenue;
    current.conversion_value += revenue;
    current.conversions += conversions;
    current.clicks += clicks;
    current.impressions += impressions;
    current.wasted_spend += num(row.wasted_spend);
    byCampaign.set(key, current);
  }
  const campaigns = [...byCampaign.values()].map((item) => ({
    ...item,
    ctr: ratio(item.clicks, item.impressions),
    cpc: ratio(item.spend, item.clicks),
    cpa: ratio(item.spend, item.conversions),
    roas: ratio(item.revenue, item.spend)
  }));
  const topCampaigns = [...campaigns]
    .filter((item) => item.spend > 0 && item.roas !== null)
    .sort((a, b) => (b.roas || 0) - (a.roas || 0) || b.conversions - a.conversions)
    .slice(0, 5)
    .map(({ campaign_name, spend, revenue, conversion_value, roas, conversions, cpa }) => ({ campaign_name, spend, revenue, conversion_value, roas, conversions, cpa }));
  const topKeys = new Set(topCampaigns.map((item) => item.campaign_name));
  const avgCpa = ratio(totals.spend, totals.conversions);
  const campaignsToWatch = [...campaigns]
    .filter((item) => !topKeys.has(item.campaign_name))
    .map((item) => ({
      ...item,
      reason: item.conversions === 0 && item.spend > 0 ? 'Spend without recorded conversions' : item.cpa !== null && avgCpa !== null && item.cpa > avgCpa * 1.5 ? 'CPA is materially above account average' : item.roas !== null && item.roas < 1 ? 'ROAS is below break-even' : item.wasted_spend > 0 ? 'Wasted spend is being tracked' : ''
    }))
    .filter((item) => item.reason)
    .sort((a, b) => b.spend - a.spend)
    .slice(0, 5)
    .map(({ campaign_name, reason, spend, conversions, cpa, roas }) => ({ campaign_name, reason, spend, conversions, cpa, roas }));
  return {
    ...totals,
    ctr: ratio(totals.clicks, totals.impressions),
    cpc: ratio(totals.spend, totals.clicks),
    cpa: ratio(totals.spend, totals.conversions),
    roas: ratio(totals.revenue, totals.spend),
    top_campaigns: topCampaigns,
    campaigns_to_watch: campaignsToWatch
  };
}
function avgPosition(rows) {
  let total = 0;
  let weight = 0;
  for (const row of rows) {
    const position = nullableNum(row.average_position ?? row.position);
    if (position === null) continue;
    const impressions = num(row.organic_impressions ?? row.impressions);
    const rowWeight = impressions > 0 ? impressions : 1;
    total += position * rowWeight;
    weight += rowWeight;
  }
  return weight > 0 ? total / weight : null;
}
function aggregateKeywordRows(rawRows) {
  const map = new Map();
  for (const row of rawRows) {
    const key = String(row.query || row.keyword || 'Unknown query');
    const current = map.get(key) || { query: key, clicks: 0, impressions: 0, position_total: 0, position_weight: 0 };
    const clicks = num(row.organic_clicks ?? row.clicks);
    const impressions = num(row.organic_impressions ?? row.impressions);
    const position = nullableNum(row.average_position ?? row.position);
    current.clicks += clicks;
    current.impressions += impressions;
    if (position !== null) {
      const rowWeight = impressions > 0 ? impressions : 1;
      current.position_total += position * rowWeight;
      current.position_weight += rowWeight;
    }
    map.set(key, current);
  }
  return [...map.values()].map((item) => ({
    query: item.query,
    clicks: item.clicks,
    impressions: item.impressions,
    ctr: ratio(item.clicks, item.impressions),
    position: item.position_weight > 0 ? item.position_total / item.position_weight : null
  })).sort((a, b) => b.clicks - a.clicks || b.impressions - a.impressions).slice(0, 10);
}
function normalizePage(value) {
  const raw = String(value || 'Unknown page');
  try {
    const url = new URL(raw.startsWith('http') ? raw : 'https://www.thepressburger.com' + (raw.startsWith('/') ? raw : '/' + raw));
    url.hash = '';
    url.search = '';
    url.hostname = url.hostname.toLowerCase();
    if (url.pathname !== '/') url.pathname = url.pathname.replace(/\/$/, '');
    return url.origin + (url.pathname || '/');
  } catch {
    return raw.split('#')[0].split('?')[0].replace(/\/$/, '') || raw;
  }
}
function aggregatePageRows(rawRows) {
  const map = new Map();
  for (const row of rawRows) {
    const key = normalizePage(row.page ?? row.landing_page ?? row.url);
    const current = map.get(key) || { page: key, clicks: 0, impressions: 0, outbound_clicks: null, position_total: 0, position_weight: 0 };
    const clicks = num(row.organic_clicks ?? row.clicks);
    const impressions = num(row.organic_impressions ?? row.impressions);
    const outbound = nullableNum(row.outbound_clicks);
    const position = nullableNum(row.average_position ?? row.position);
    current.clicks += clicks;
    current.impressions += impressions;
    if (outbound !== null) current.outbound_clicks = (current.outbound_clicks ?? 0) + outbound;
    if (position !== null) {
      const rowWeight = impressions > 0 ? impressions : 1;
      current.position_total += position * rowWeight;
      current.position_weight += rowWeight;
    }
    map.set(key, current);
  }
  return [...map.values()].map((item) => ({
    page: item.page,
    clicks: item.clicks,
    impressions: item.impressions,
    ctr: ratio(item.clicks, item.impressions),
    position: item.position_weight > 0 ? item.position_total / item.position_weight : null,
    outbound_clicks: item.outbound_clicks,
    outbound_click_rate: item.outbound_clicks !== null ? ratio(item.outbound_clicks, item.clicks) : null
  })).sort((a, b) => b.clicks - a.clicks || b.impressions - a.impressions).slice(0, 10);
}
function latestIndexedPages(rawRows) {
  const sorted = [...rawRows].filter((row) => nullableNum(row.indexed_pages) !== null).sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
  return sorted.length ? nullableNum(sorted[0].indexed_pages) : null;
}
function aggregateSeo(dailyRows, keywordRows, pageRows) {
  if (!dailyRows.length && !keywordRows.length && !pageRows.length) return null;
  const organicClicks = dailyRows.reduce((sum, row) => sum + num(row.organic_clicks ?? row.clicks), 0);
  const organicImpressions = dailyRows.reduce((sum, row) => sum + num(row.organic_impressions ?? row.impressions), 0);
  const organicSessions = dailyRows.reduce((sum, row) => sum + num(row.organic_sessions ?? row.sessions), 0);
  const organicConversions = dailyRows.reduce((sum, row) => sum + num(row.organic_conversions ?? row.conversions), 0);
  const outboundValues = dailyRows.map((row) => nullableNum(row.outbound_clicks)).filter((value) => value !== null);
  const outboundClicks = outboundValues.length ? outboundValues.reduce((sum, value) => sum + value, 0) : null;
  const topQueries = aggregateKeywordRows(keywordRows);
  const topPages = aggregatePageRows(pageRows);
  const summary = {
    organic_clicks: organicClicks,
    organic_impressions: organicImpressions,
    organic_ctr: ratio(organicClicks, organicImpressions),
    average_position: avgPosition(dailyRows),
    organic_sessions: organicSessions,
    organic_conversions: organicConversions,
    outbound_clicks: outboundClicks,
    outbound_click_rate: outboundClicks !== null ? ratio(outboundClicks, organicClicks) : null,
    indexed_pages: latestIndexedPages(dailyRows),
    top_queries: topQueries,
    top_landing_pages: topPages,
    organic_growth_opportunities: []
  };
  summary.organic_growth_opportunities = buildOpportunities(topQueries, topPages);
  return summary;
}
function buildOpportunities(queries, pages) {
  const opportunities = [];
  for (const page of pages) {
    const lowCtr = page.impressions >= 100 && page.ctr !== null && page.ctr < 0.025;
    const lowOutbound = page.clicks >= 5 && page.outbound_clicks !== null && page.outbound_clicks <= 0;
    const nearPageOne = page.position !== null && page.position >= 4 && page.position <= 15;
    if (!lowCtr && !lowOutbound && !nearPageOne) continue;
    const pageText = page.page.toLowerCase();
    const action = pageText.includes('catering') ? 'Prioritize catering CTA clarity and lead capture.' : pageText.includes('menu') || pageText.includes('order') ? 'Prioritize order-now visibility and menu/order structured data.' : 'Improve local relevance, internal links, and above-the-fold action paths.';
    opportunities.push({ opportunity: page.page, signal: [page.clicks + ' clicks', page.impressions + ' impressions', page.ctr !== null ? (page.ctr * 100).toFixed(1) + '% CTR' : null, page.position !== null ? 'avg position ' + page.position.toFixed(1) : null, page.outbound_clicks !== null ? page.outbound_clicks + ' outbound clicks' : null].filter(Boolean).join(', '), why_it_matters: lowOutbound ? 'This page is gaining organic visibility but may not be driving enough measurable ordering, location, or catering actions.' : lowCtr ? 'This page is showing in organic search but may not be winning enough clicks.' : 'This page is close to stronger page-one visibility.', recommended_action: action });
  }
  for (const query of queries) {
    const lowCtr = query.impressions >= 100 && query.ctr !== null && query.ctr < 0.025;
    const nearPageOne = query.position !== null && query.position >= 4 && query.position <= 15;
    if (!lowCtr && !nearPageOne) continue;
    opportunities.push({ opportunity: query.query, signal: [query.clicks + ' clicks', query.impressions + ' impressions', query.ctr !== null ? (query.ctr * 100).toFixed(1) + '% CTR' : null, query.position !== null ? 'avg position ' + query.position.toFixed(1) : null].filter(Boolean).join(', '), why_it_matters: lowCtr ? 'This query has visibility but the search result may not be compelling enough to win clicks.' : 'This query is close to stronger page-one visibility.', recommended_action: lowCtr ? 'Improve title tag and meta description around query intent.' : 'Strengthen content, internal links, schema, and local relevance.' });
  }
  return opportunities.slice(0, 8);
}
const paidCurrent = aggregatePaid(rows('Fetch Paid Ads - Current Month'));
const paidPrevious = aggregatePaid(rows('Fetch Paid Ads - Previous Month'));
const seoCurrent = aggregateSeo(rows('Fetch SEO Daily - Current Month'), rows('Fetch SEO Queries - Current Month'), rows('Fetch SEO Pages - Current Month'));
const seoPrevious = aggregateSeo(rows('Fetch SEO Daily - Previous Month'), [], []);
const mom = {
  paid_ads: {
    spend_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.spend, paidPrevious.spend) : null,
    conversions_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.conversions, paidPrevious.conversions) : null,
    cpa_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.cpa, paidPrevious.cpa) : null,
    roas_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.roas, paidPrevious.roas) : null,
    revenue_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.revenue, paidPrevious.revenue) : null,
    conversion_value_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.conversion_value, paidPrevious.conversion_value) : null,
    clicks_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.clicks, paidPrevious.clicks) : null,
    ctr_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.ctr, paidPrevious.ctr) : null,
    cpc_mom: paidCurrent && paidPrevious ? pctChange(paidCurrent.cpc, paidPrevious.cpc) : null,
    current: paidCurrent,
    previous: paidPrevious
  },
  seo: {
    organic_clicks_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.organic_clicks, seoPrevious.organic_clicks) : null,
    organic_impressions_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.organic_impressions, seoPrevious.organic_impressions) : null,
    organic_ctr_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.organic_ctr, seoPrevious.organic_ctr) : null,
    average_position_change: seoCurrent && seoPrevious && seoCurrent.average_position !== null && seoPrevious.average_position !== null ? seoCurrent.average_position - seoPrevious.average_position : null,
    organic_sessions_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.organic_sessions, seoPrevious.organic_sessions) : null,
    outbound_clicks_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.outbound_clicks, seoPrevious.outbound_clicks) : null,
    outbound_click_rate_mom: seoCurrent && seoPrevious ? pctChange(seoCurrent.outbound_click_rate, seoPrevious.outbound_click_rate) : null,
    current: seoCurrent,
    previous: seoPrevious
  }
};
return [{ json: { ...config, paid_ads_summary: paidCurrent, previous_paid_ads_summary: paidPrevious, seo_summary: seoCurrent, previous_seo_summary: seoPrevious, mom_summary: mom, has_paid_data: Boolean(paidCurrent), has_seo_data: Boolean(seoCurrent), has_any_data: Boolean(paidCurrent || seoCurrent) } }];

