const data = $('Aggregate Monthly Report Data').first().json;
const response = $('OpenAI - Generate Report Commentary').first()?.json || {};
const fallback = {
  executive_summary: 'Monthly report metrics were generated, but AI commentary generation failed. Review the metric summaries before publishing.',
  paid_ads_commentary: data.paid_ads_summary ? 'Paid Ads metrics are available for this report. Commentary should be reviewed manually before publishing.' : 'Paid Ads data not available for this report.',
  seo_commentary: data.seo_summary ? 'SEO metrics are available for this report. Commentary should be reviewed manually before publishing.' : 'SEO data not available for this report.',
  mom_commentary: 'Month-over-month comparisons are available where prior month data existed. Commentary should be reviewed manually before publishing.',
  wins: [],
  watchouts: ['AI commentary generation failed or returned invalid JSON.'],
  next_steps: ['Review the metric summaries and add final commentary before publishing.']
};
let content = response.choices?.[0]?.message?.content;
let parsed = null;
try { parsed = typeof content === 'string' ? JSON.parse(content) : null; } catch (error) { parsed = null; }
const commentary = parsed && typeof parsed === 'object' ? parsed : fallback;
if (data.seo_summary?.outbound_click_rate !== null && data.seo_summary?.outbound_click_rate > 1) {
  commentary.watchouts = [...(Array.isArray(commentary.watchouts) ? commentary.watchouts : []), 'Outbound click rate is above 100%, which may indicate tracking duplication or broader attribution scope that should be reviewed.'];
}
return [{ json: { ...data, ...commentary } }];

const saved = $json;
